import crypto from 'crypto';
import fs from 'node:fs/promises';
import path from 'node:path';

/**
 * Recursively finds all `.html` files inside a directory and returns their absolute paths.
 * @param dir - Absolute directory path to scan.
 * @returns Sorted array of absolute HTML file paths.
 */
export async function findHtmlFiles(dir: string): Promise<string[]> {
  try {
    const entries = await fs.readdir(dir, { withFileTypes: true, recursive: true });
    return entries
      .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith('.html'))
      .map((entry) => path.join(entry.parentPath, entry.name))
      .sort();
  } catch {
    return [];
  }
}

/**
 * Default environment variable names for supported AI providers.
 */
const PROVIDER_ENV_KEYS: Record<string, string> = {
  openai: 'OPENAI_API_KEY',
  'openai-compatible': 'OPENAI_API_KEY',
  gemini: 'GEMINI_API_KEY',
  claude: 'ANTHROPIC_API_KEY',
  anthropic: 'ANTHROPIC_API_KEY',
  mistral: 'MISTRAL_API_KEY',
  deepseek: 'DEEPSEEK_API_KEY',
  groq: 'GROQ_API_KEY',
  openrouter: 'OPENROUTER_API_KEY',
  xai: 'XAI_API_KEY',
  perplexity: 'PERPLEXITY_API_KEY',
  cohere: 'COHERE_API_KEY',
  together: 'TOGETHER_API_KEY',
  fireworks: 'FIREWORKS_API_KEY',
  'azure-openai': 'AZURE_OPENAI_API_KEY',
};

/**
 * Resolves the fallback environment variable API key for a given provider.
 * @param provider - The AI provider identifier.
 * @returns The API key from environment variables, or an empty string.
 */
export function resolveProviderApiKey(provider?: string): string {
  if (!provider) return '';
  const envKey = PROVIDER_ENV_KEYS[provider];
  if (envKey && process.env[envKey]) {
    return process.env[envKey];
  }
  return process.env.AI_API_KEY || '';
}

/**
 * Generates a SHA256 hash for a given string.
 * @param input The input string
 * @returns The SHA256 hash as hex string
 */
export function sha256(input: string): string {
  return crypto.createHash('sha256').update(input).digest('hex');
}

/**
 * Removes local path parts and normalizes slashes (OS-independent).
 * @param inputPath The path string
 * @returns The cleaned path
 */
export function cleanPath(inputPath: string): string {
  // Entfernt Backslashes und Slashes, normalisiert den Pfad OS-unabhängig
  return inputPath.replace(/[\\/]+/g, '/');
}

/**
 * Checks whether a relative URL path matches any of the configured exclude patterns.
 * Supports exact matches, prefix matches, `*` single-segment wildcards, and `**` multi-segment wildcards.
 * @param relUrl - Normalized relative URL (e.g., '/blog/draft', '/404').
 * @param patterns - Array of exclude patterns (e.g., ['/404', '/admin/**']).
 * @returns True if the path should be excluded.
 */
export function isExcludedPath(relUrl: string, patterns?: string[]): boolean {
  if (!patterns || patterns.length === 0) return false;
  const normalizedTarget = cleanPath(relUrl);

  return patterns.some((rawPattern) => {
    const pattern = cleanPath(rawPattern.trim());
    if (!pattern) return false;

    const normalizedPattern = pattern.startsWith('/') ? pattern : `/${pattern}`;
    if (normalizedTarget === normalizedPattern) return true;

    const escaped = normalizedPattern
      .replace(/[.+?^${}()|[\]\\]/g, '\\$&')
      .replace(/\*\*/g, '___DOUBLE_STAR___')
      .replace(/\*/g, '[^/]*')
      .replace(/___DOUBLE_STAR___/g, '.*');

    const regex = new RegExp(`^${escaped}$`);
    return regex.test(normalizedTarget);
  });
}

/**
 * Outputs debug logs if DEBUG_LLMS_TXT=1 is set.
 * @param args Arbitrary arguments for logging
 */
export function debugLog(...args: string[]) {
  if (process.env.DEBUG_LLMS_TXT === '1') {
    // eslint-disable-next-line no-console
    console.log('[llms-txt]', ...args);
  }
}
